// Mango Tango results page (/results): the 2026 party report, interactive.
// Data comes from report-data.json (generated by scripts/build-report-data.py
// from the all-votes export); catalog details reuse shared/mangoes.json and
// the guest app's markdown renderer.

import { render } from 'preact';
import { signal } from '@preact/signals';
import { useEffect, useRef, useState } from 'preact/hooks';
import { renderMarkdown } from '../app/md';
import { startNectar } from '../app/shader';
import CATALOG from '../../shared/mangoes.json';
import REPORT from './report-data.json';
import '../styles/tokens.css';
import '../styles/app.css';
import './results.css';

interface MangoStat {
  name: string;
  n: number;
  mean: number;
  med: number;
  sd: number;
  min: number;
  max: number;
  dist: number[];
  subMean: number | null;
  subN: number;
  rank: number;
  subRank?: number;
}

const MANGOES = REPORT.mangoes as MangoStat[];
const byName = new Map(MANGOES.map((m) => [m.name, m]));
const catalogByName = new Map(CATALOG.map((c) => [c.name, c]));

/** Which mango's detail modal is open (read during render — signals rule!). */
const modalFor = signal<MangoStat | null>(null);

const fmt = (x: number) => x.toFixed(2);

// ---------------------------------------------------------------------------
// Shared tooltip: one per chart container, positioned locally.
// Tooltips enhance, never gate — every value also lives in labels/tables.
// ---------------------------------------------------------------------------

interface TipState {
  x: number;
  y: number;
  title: string;
  rows: Array<[string, string]>;
}

function useTip() {
  const boxRef = useRef<HTMLDivElement>(null);
  const [tip, setTip] = useState<TipState | null>(null);

  const show = (el: Element, title: string, rows: Array<[string, string]>): void => {
    const box = boxRef.current;
    if (!box) return;
    const b = box.getBoundingClientRect();
    const r = el.getBoundingClientRect();
    const x = Math.min(Math.max(r.left + r.width / 2 - b.left, 56), b.width - 56);
    setTip({ x, y: r.top - b.top, title, rows });
  };
  const hide = (): void => setTip(null);

  const node = tip ? (
    <div class="tip" style={`left:${tip.x}px;top:${tip.y}px`}>
      <div class="t">{tip.title}</div>
      {tip.rows.map(([k, v]) => (
        <div class="r" key={k}>
          <span>{k}</span>
          <span>{v}</span>
        </div>
      ))}
    </div>
  ) : null;

  return { boxRef, show, hide, node };
}

// ---------------------------------------------------------------------------

function Hero() {
  const m = REPORT.meta;
  return (
    <header class="hero rhero">
      <p class="crumbs">
        <a href="/">🥭 Mango Tango</a> · {m.date}
      </p>
      <h1>
        <span class="line1" aria-label="Results">
          {'RESULTS'.split('').map((ch, i) => (
            <b key={i} style={`--n:${i}`}>
              {ch}
            </b>
          ))}
        </span>
        <span class="line2">
          THE VERDICT <span class="fruit">🏆</span>
        </span>
      </h1>
      <div class="metaChips">
        <span>👅 {m.tasters} tasters</span>
        <span>🥭 {m.mangoesTasted} mangoes</span>
        <span>🗳 {m.votes} votes</span>
        <span>👑 one champion</span>
      </div>
    </header>
  );
}

function Podium() {
  const [gold, silver, bronze] = MANGOES;
  const spot = (m: MangoStat, medal: string, cls: string) => (
    <button class={`podiumSpot ${cls}`} onClick={() => (modalFor.value = m)}>
      <span class="medal" aria-hidden="true">{medal}</span>
      <span class="pname">{m.name}</span>
      <span class="pscore">{fmt(m.mean)}</span>
      <span class="pnote">avg of {m.n} votes</span>
    </button>
  );
  return (
    <section class="podium" aria-label="Podium">
      {spot(silver, '🥈', 'second')}
      {spot(gold, '🥇', 'first')}
      {spot(bronze, '🥉', 'third')}
    </section>
  );
}

function Standings() {
  const { boxRef, show, hide, node } = useTip();
  const medal = (r: number) => (r === 1 ? '🥇' : r === 2 ? '🥈' : r === 3 ? '🥉' : String(r));
  return (
    <section class="rcard">
      <h2>📊 Full standings</h2>
      <p class="sub">
        Every vote counted — drafts included. Tap a mango for its story; hover for the fine print.
      </p>
      <div class="chartBox" ref={boxRef}>
        <div class="standRows">
          {MANGOES.map((m, i) => (
            <button
              class="standRow"
              key={m.name}
              style={`animation-delay:${i * 30}ms`}
              onClick={() => (modalFor.value = m)}
              onPointerEnter={(e) =>
                show(e.currentTarget, m.name, [
                  ['mean', fmt(m.mean)],
                  ['median', String(m.med)],
                  ['spread σ', fmt(m.sd)],
                  ['votes', String(m.n)],
                  ['range', `${m.min}–${m.max}`],
                ])
              }
              onPointerLeave={hide}
              onFocus={(e) => show(e.currentTarget, m.name, [['mean', fmt(m.mean)], ['votes', String(m.n)]])}
              onBlur={hide}
            >
              <span class={`rk ${m.rank <= 3 ? 'medal' : ''}`}>{medal(m.rank)}</span>
              <span class="nm">{m.name}</span>
              <span class="barWrap">
                <span
                  class="bar"
                  style={`width:${(m.mean / 10) * 100}%;animation-delay:${i * 30}ms`}
                  aria-hidden="true"
                />
                <span class="val">{fmt(m.mean)}</span>
              </span>
            </button>
          ))}
        </div>
        {node}
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------
// Controversy map — mean (x) vs spread (y) scatter.
// ---------------------------------------------------------------------------

function ControversyMap() {
  const { boxRef, show, hide, node } = useTip();
  const W = 520;
  const H = 330;
  const P = { l: 34, r: 14, t: 26, b: 30 };
  const xMin = 2;
  const xMax = 8.4;
  const yMin = 1.0;
  const yMax = 2.85;
  const X = (v: number) => P.l + ((v - xMin) / (xMax - xMin)) * (W - P.l - P.r);
  const Y = (v: number) => H - P.b - ((v - yMin) / (yMax - yMin)) * (H - P.t - P.b);
  const midX = 5.5;
  const midY = 1.85;
  const labeled = new Set(['Lemon Zest', 'Sindhiri', 'Tierno', 'ST Maui', 'Kathy']);

  return (
    <section class="rcard">
      <h2>⚔️ The controversy map</h2>
      <p class="sub">
        Right = the room liked it; up = the room <b>fought about it</b>. <b>Sindhiri</b> got both
        a 1 and two 10s at the same table. <b>Lemon Zest</b> won while starting zero arguments.
      </p>
      <div class="chartBox" ref={boxRef}>
        <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Scatter plot of mean score versus score spread for each mango">
          {/* hairline frame + midlines */}
          <line class="hairline" x1={P.l} y1={H - P.b} x2={W - P.r} y2={H - P.b} />
          <line class="hairline" x1={P.l} y1={P.t} x2={P.l} y2={H - P.b} />
          <line class="hairline" x1={X(midX)} y1={P.t} x2={X(midX)} y2={H - P.b} stroke-dasharray="none" opacity="0.6" />
          <line class="hairline" x1={P.l} y1={Y(midY)} x2={W - P.r} y2={Y(midY)} opacity="0.6" />
          {[3, 4, 5, 6, 7, 8].map((v) => (
            <text class="axisText" key={v} x={X(v)} y={H - P.b + 14} text-anchor="middle">
              {v}
            </text>
          ))}
          {[1.5, 2.0, 2.5].map((v) => (
            <text class="axisText" key={v} x={P.l - 6} y={Y(v) + 3} text-anchor="end">
              {v.toFixed(1)}
            </text>
          ))}
          <text class="axisText" x={W - P.r} y={H - 4} text-anchor="end">
            mean score →
          </text>
          <text class="axisText" x={12} y={P.t - 8}>
            ↑ disagreement (σ)
          </text>
          {/* quadrant moods */}
          <text class="quadText" x={X(midX) + 8} y={P.t + 4}>love it or hate it</text>
          <text class="quadText" x={X(midX) + 8} y={H - P.b - 8}>undisputed hits</text>
          <text class="quadText" x={P.l + 6} y={P.t + 4}>chaotic flops</text>
          <text class="quadText" x={P.l + 6} y={H - P.b - 8}>agreed: pass</text>
          {/* selective labels */}
          {MANGOES.filter((m) => labeled.has(m.name)).map((m) => (
            <text
              class="dotLabel"
              key={m.name}
              x={X(m.mean)}
              y={Y(m.sd) - 11}
              text-anchor={m.mean > 7 ? 'end' : 'middle'}
            >
              {m.name}
            </text>
          ))}
          {/* dots: ≥8px marks with a 2px surface ring; 28px invisible hit area */}
          {MANGOES.map((m) => (
            <g key={m.name}>
              <circle
                class="hit"
                cx={X(m.mean)}
                cy={Y(m.sd)}
                r={14}
                tabIndex={0}
                role="button"
                aria-label={`${m.name}: mean ${fmt(m.mean)}, spread ${fmt(m.sd)}. Open details.`}
                onClick={() => (modalFor.value = m)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    modalFor.value = m;
                  }
                }}
                onPointerEnter={(e) =>
                  show(e.currentTarget, m.name, [
                    ['mean', fmt(m.mean)],
                    ['spread σ', fmt(m.sd)],
                    ['votes', String(m.n)],
                  ])
                }
                onPointerLeave={hide}
                onFocus={(e) => show(e.currentTarget, m.name, [['mean', fmt(m.mean)], ['spread σ', fmt(m.sd)]])}
                onBlur={hide}
              />
              <circle class="dot" cx={X(m.mean)} cy={Y(m.sd)} r={5.5} style="pointer-events:none" />
            </g>
          ))}
        </svg>
        {node}
      </div>
      <details class="tableView">
        <summary>Table view</summary>
        <table>
          <thead>
            <tr><th>Mango</th><th>Mean</th><th>σ</th><th>Votes</th></tr>
          </thead>
          <tbody>
            {MANGOES.map((m) => (
              <tr key={m.name}>
                <td>{m.name}</td>
                <td>{fmt(m.mean)}</td>
                <td>{fmt(m.sd)}</td>
                <td>{m.n}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </details>
    </section>
  );
}

// ---------------------------------------------------------------------------
// Histogram of every score cast (also reused small inside the modal).
// ---------------------------------------------------------------------------

function Histogram({ counts, height = 150, labelPeak = true }: { counts: number[]; height?: number; labelPeak?: boolean }) {
  const { boxRef, show, hide, node } = useTip();
  const W = 520;
  const H = height;
  const P = { l: 26, r: 6, t: 18, b: 22 };
  const max = Math.max(...counts, 1);
  const total = counts.reduce((a, b) => a + b, 0);
  const band = (W - P.l - P.r) / 10;
  const barW = Math.min(band - 2, 34); // 2px surface gap between columns
  const peak = counts.indexOf(max);
  const ticks = max > 40 ? [25, 50, 75] : max > 8 ? [5, 10] : [2, 4];

  return (
    <div class="chartBox" ref={boxRef}>
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Histogram of scores 1 to 10">
        {ticks.filter((t) => t <= max).map((t) => (
          <g key={t}>
            <line
              class="hairline"
              x1={P.l}
              y1={H - P.b - ((H - P.t - P.b) * t) / max}
              x2={W - P.r}
              y2={H - P.b - ((H - P.t - P.b) * t) / max}
            />
            <text class="axisText" x={P.l - 5} y={H - P.b - ((H - P.t - P.b) * t) / max + 3} text-anchor="end">
              {t}
            </text>
          </g>
        ))}
        <line class="hairline" x1={P.l} y1={H - P.b} x2={W - P.r} y2={H - P.b} />
        {counts.map((c, i) => {
          const h = ((H - P.t - P.b) * c) / max;
          const x = P.l + i * band + (band - barW) / 2;
          const y = H - P.b - h;
          return (
            <g key={i}>
              <rect
                class="hit"
                x={P.l + i * band}
                y={P.t}
                width={band}
                height={H - P.t - P.b}
                tabIndex={0}
                onPointerEnter={(e) =>
                  show(e.currentTarget, `score ${i + 1}`, [
                    ['votes', String(c)],
                    ['share', `${((c / total) * 100).toFixed(1)}%`],
                  ])
                }
                onPointerLeave={hide}
                onFocus={(e) => show(e.currentTarget, `score ${i + 1}`, [['votes', String(c)]])}
                onBlur={hide}
              />
              {c > 0 ? (
                <path
                  class="colRect"
                  style="pointer-events:none"
                  d={`M${x},${H - P.b} v${-(Math.max(h, 4) - 4)} q0,-4 4,-4 h${barW - 8} q4,0 4,4 v${Math.max(h, 4) - 4} z`}
                />
              ) : null}
              {labelPeak && i === peak ? (
                <text class="axisText" x={x + barW / 2} y={y - 5} text-anchor="middle" font-weight="700">
                  {c}
                </text>
              ) : null}
              <text class="axisText" x={P.l + i * band + band / 2} y={H - P.b + 14} text-anchor="middle">
                {i + 1}
              </text>
            </g>
          );
        })}
      </svg>
      {node}
    </div>
  );
}

function RoomScores() {
  const tens = REPORT.totalTens as number;
  const total = REPORT.meta.votes as number;
  return (
    <section class="rcard">
      <h2>🎯 How the room scored</h2>
      <p class="sub">
        A healthy bell curve centered on 6. The room used the whole scale but guarded its 10s —
        only <b>{tens} of {total} votes</b> ({((tens / total) * 100).toFixed(1)}%) were perfect scores,
        and nearly half of those came from one very generous taster.
      </p>
      <Histogram counts={REPORT.histogram as number[]} />
    </section>
  );
}

// ---------------------------------------------------------------------------
// Ballot-box effect — dumbbell of rank with vs. without draft votes.
// ---------------------------------------------------------------------------

function BallotBox() {
  const { boxRef, show, hide, node } = useTip();
  const movers = REPORT.movers as Array<{ name: string; all: number; sub: number }>;
  const N = REPORT.meta.mangoesTasted as number;
  const X = (rank: number) => 4 + ((rank - 1) / (N - 1)) * 92; // percent, #1 left

  return (
    <section class="rcard">
      <h2>🗳 The ballot-box effect</h2>
      <p class="sub">
        {REPORT.meta.tasters - REPORT.meta.submitted} of {REPORT.meta.tasters} tasters never pressed
        submit — and their draft votes move the board. <b>Sweet Tart's silver medal exists only
        because of them.</b>
      </p>
      <div class="legend" aria-hidden="true">
        <span><i style="background:var(--mark-light)" />submitted ballots only</span>
        <span><i style="background:var(--mark)" />every vote</span>
      </div>
      <div class="chartBox" ref={boxRef}>
        <div class="dumbRows">
          {movers.map((mv) => {
            const m = byName.get(mv.name);
            const x1 = X(mv.sub);
            const x2 = X(mv.all);
            const up = mv.all < mv.sub;
            return (
              <button
                class="dumbRow"
                key={mv.name}
                onClick={() => m && (modalFor.value = m)}
                onPointerEnter={(e) =>
                  show(e.currentTarget, mv.name, [
                    ['submitted only', `#${mv.sub}`],
                    ['every vote', `#${mv.all}`],
                  ])
                }
                onPointerLeave={hide}
                onFocus={(e) => show(e.currentTarget, mv.name, [['submitted', `#${mv.sub}`], ['all votes', `#${mv.all}`]])}
                onBlur={hide}
              >
                <span class="nm">{mv.name}</span>
                <svg viewBox="0 0 100 22" preserveAspectRatio="none" aria-hidden="true">
                  <line class="hairline" x1="4" y1="11" x2="96" y2="11" />
                  <line x1={x1} y1="11" x2={x2} y2="11" stroke="var(--mark)" stroke-width="2" opacity="0.55" />
                  <circle cx={x1} cy="11" r="5" fill="var(--mark-light)" stroke="oklch(0.99 0.02 95)" stroke-width="2" vector-effect="non-scaling-stroke" />
                  <circle cx={x2} cy="11" r="5" fill="var(--mark)" stroke="oklch(0.99 0.02 95)" stroke-width="2" vector-effect="non-scaling-stroke" />
                </svg>
                <span class="delta">{up ? '▲' : '▼'} {Math.abs(mv.all - mv.sub)}</span>
              </button>
            );
          })}
        </div>
        <div class="dumbAxis" aria-hidden="true">
          <span />
          <span class="ticks"><span>#1 best</span><span>#{N}</span></span>
          <span />
        </div>
        {node}
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------

function Superlatives() {
  const t = REPORT.tasters as Array<{ label: string; mean: number; sd: number; tens: number; ones: number }>;
  const generous = t[0];
  const harshest = t[t.length - 1];
  const steadiest = [...t].sort((a, b) => a.sd - b.sd)[0];
  const twins = (REPORT.twins as Array<{ a: string; b: string; r: number }>)[0];
  const opp = (REPORT.opposites as Array<{ a: string; b: string; r: number }>)[0];
  const oracle = (REPORT.oracle as Array<{ label: string; r: number }>)[0];
  const tiles: Array<[string, string, string]> = [
    ['Most generous', generous.label, `mean ${fmt(generous.mean)} — and ${generous.tens} of the party's ${REPORT.totalTens} perfect 10s`],
    ['Toughest crowd', harshest.label, `mean ${fmt(harshest.mean)} — ${harshest.ones} brutal 1s, zero 10s`],
    ['Steadiest palate', steadiest.label, `σ ${fmt(steadiest.sd)} — the human moving average`],
    ['Palate twins', `${twins.a} & ${twins.b}`, `r = ${twins.r} — if one likes it, the other already does`],
    ['Palate opposites', `${opp.a} & ${opp.b}`, `r = ${opp.r} — never let them split a mango`],
    ['The crowd oracle', oracle.label, `r = ${oracle.r} with the room's average — the median mango eater`],
    ['Busiest host', 'The host', 'rated exactly two mangoes — too busy running the show to eat'],
    ['Never made the table', (REPORT.meta.neverRated as string[]).join(' & '), 'on the list, zero votes — they never met the knife'],
  ];
  return (
    <section class="rcard">
      <h2>🏅 Taster superlatives</h2>
      <p class="sub">{REPORT.meta.tasters} tasters, statistically exposed.</p>
      <div class="tiles2">
        {tiles.map(([l, v, c]) => (
          <div class="tile2" key={l}>
            <span class="tl">{l}</span>
            <span class="tv">{v}</span>
            <span class="tc">{c}</span>
          </div>
        ))}
      </div>
    </section>
  );
}

function Takeaways() {
  return (
    <section class="rcard">
      <h2>🔭 For next year</h2>
      <ol class="takeaways">
        <li><b>Bring more Lemon Zest</b> — the Zill citrus program swept: three of the top eight are citrus-flavored siblings.</li>
        <li><b>Find out what Kathy is.</b> A write-in beat nearly the entire curated catalog. It deserves a name and a story.</li>
        <li><b>Skip Tierno and Haden.</b> If you want the Haden experience, Bailey's Marvel is the strictly better version (+2.6 points over its parent).</li>
        <li><b>Serve Sindhiri anyway.</b> Both 10s and a 1 at the same table — controversy is content.</li>
        <li><b>Get people to press submit.</b> Half the room never did. (The button bug is fixed; next year the drafts gap should close on its own.)</li>
      </ol>
    </section>
  );
}

// ---------------------------------------------------------------------------

function MangoModal() {
  const m = modalFor.value; // read during render — subscribes this component
  const ref = useRef<HTMLDialogElement>(null);
  const last = useRef<MangoStat | null>(null);
  if (m) last.current = m;
  const shown = m ?? last.current;

  useEffect(() => {
    const d = ref.current;
    if (!d) return;
    if (m && !d.open) d.showModal();
    if (!m && d.open) d.close();
  });

  const cat = shown ? catalogByName.get(shown.name) : undefined;
  return (
    <dialog class="sheet" ref={ref} onClose={() => (modalFor.value = null)} closedby="any">
      {shown ? (
        <div class="sheetInner">
          <div class="grabber" aria-hidden="true" />
          <h2>🥭 {shown.name}</h2>
          <p class="modalRank">
            Finished <b>#{shown.rank}</b> of {MANGOES.length}
            {shown.subRank && shown.subRank !== shown.rank ? ` (#${shown.subRank} on submitted ballots)` : ''}
            {' · '}scores ranged {shown.min}–{shown.max}
          </p>
          <div class="modalStats">
            <div class="mstat"><b>{fmt(shown.mean)}</b><span>mean</span></div>
            <div class="mstat"><b>{shown.med}</b><span>median</span></div>
            <div class="mstat"><b>{fmt(shown.sd)}</b><span>spread σ</span></div>
            <div class="mstat"><b>{shown.n}</b><span>votes</span></div>
          </div>
          <div>
            <p class="miniHistTitle">The room's votes, 1–10</p>
            <Histogram counts={shown.dist} height={110} labelPeak={false} />
          </div>
          {cat ? (
            <div class="mdBody" dangerouslySetInnerHTML={{ __html: renderMarkdown(cat.details) }} />
          ) : (
            <p class="writeIn">
              🎉 A party write-in — this mango walked in without a catalog entry and competed
              anyway{shown.rank <= 3 ? ' (and medaled!)' : ''}. If you know its story, tell the host.
            </p>
          )}
          <button class="ghost" onClick={() => (modalFor.value = null)}>
            Back to the results
          </button>
        </div>
      ) : null}
    </dialog>
  );
}

function App() {
  return (
    <div class="rshell">
      <Hero />
      <Podium />
      <Standings />
      <ControversyMap />
      <RoomScores />
      <BallotBox />
      <Superlatives />
      <Takeaways />
      <footer class="rfoot">
        Made with 🥭 at Mango Tango 2026 · <a href="/">rate next year's batch →</a>
      </footer>
      <MangoModal />
    </div>
  );
}

const canvas = document.getElementById('nectar') as HTMLCanvasElement | null;
if (canvas) startNectar(canvas);
render(<App />, document.getElementById('app')!);
